use std::cmp::Reverse;
use std::collections::{BinaryHeap, VecDeque};

/// Order the vertices 0 .. n-1 of a directed graph so that for every pair
/// (a, b) in deps, a comes before b. Duplicate pairs are allowed.
///
/// If such an order exists, return (true, order) where order is the
/// lexicographically smallest valid order (at each step, the smallest vertex
/// whose predecessors are all placed).
///
/// If the graph has a cycle (a pair (a, a) is a cycle of one vertex), return
/// (false, cycle): let s be the smallest vertex that lies on any cycle; cycle
/// is the shortest cycle through s, written as its vertices starting at s
/// without repeating s at the end; among shortest cycles, the
/// lexicographically smallest list.
///
/// Invalid input (n < 0, or any vertex in deps outside 0 .. n-1) returns
/// (false, vec![]), even if the graph also has a cycle. n == 0 gives (true, vec![]).
/// >>> topo_order(4, vec![(0, 1), (0, 2), (1, 3), (2, 3)])
/// (true, vec![0, 1, 2, 3])
/// >>> topo_order(3, vec![(0, 1), (1, 2), (2, 0)])
/// (false, vec![0, 1, 2])
fn topo_order(n: i64, deps: Vec<(i64, i64)>) -> (bool, Vec<i64>) {
    if n < 0 {
        return (false, vec![]);
    }
    let nu = n as usize;
    let mut succ: Vec<Vec<usize>> = vec![Vec::new(); nu];
    let mut indeg = vec![0usize; nu];
    for &(a, b) in &deps {
        if a < 0 || a >= n || b < 0 || b >= n {
            return (false, vec![]);
        }
        succ[a as usize].push(b as usize);
        indeg[b as usize] += 1;
    }
    let mut ready: BinaryHeap<Reverse<usize>> = (0..nu).filter(|&v| indeg[v] == 0).map(Reverse).collect();
    let mut order = Vec::new();
    while let Some(Reverse(v)) = ready.pop() {
        order.push(v as i64);
        for &w in &succ[v] {
            indeg[w] -= 1;
            if indeg[w] == 0 {
                ready.push(Reverse(w));
            }
        }
    }
    if order.len() == nu {
        return (true, order);
    }
    for s in 0..nu {
        // BFS with sorted successors finds lexicographically smallest shortest paths.
        let mut parent: Vec<Option<usize>> = vec![None; nu];
        let mut seen = vec![false; nu];
        seen[s] = true;
        let mut queue = VecDeque::from(vec![s]);
        while let Some(u) = queue.pop_front() {
            let mut next = succ[u].clone();
            next.sort();
            next.dedup();
            for w in next {
                if w == s {
                    let mut cycle = vec![u as i64];
                    let mut x = u;
                    while let Some(p) = parent[x] {
                        cycle.push(p as i64);
                        x = p;
                    }
                    cycle.reverse();
                    return (false, cycle);
                }
                if !seen[w] {
                    seen[w] = true;
                    parent[w] = Some(u);
                    queue.push_back(w);
                }
            }
        }
    }
    (false, vec![])
}
